contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint minSum, uint am) public payable {
        require(minSum <= type(uint).max);

        // Set an arbitrary minimum sum (no funds have ever been deposited).
        c.SetMinSum(minSum);

        uint balBefore = address(c).balance;
        uint recBefore = c.Acc(address(this)).balance;

        // Attempt to withdraw any requested amount.
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }

        uint balAfter = address(c).balance;
        uint recAfter = c.Acc(address(this)).balance;

        // General rule: with zero deposited funds, Collect never increases or
        // decreases the contract's Ether and never creates a positive recorded
        // balance, whether or not it reverts.
        assert(
            balAfter == balBefore
            && balAfter == 0
            && recAfter == recBefore
            && recAfter == 0
        );
    }

    receive() external payable {}
}

